	for (u = t; u != s; u ^= uv[h]) {
		h = (h_ = bb[u]) >> 1;
		cc[h_]--, cc[h_ ^ 1]++;
	}
#endif
}

int edmonds_karp(int s, int t) {
	int c, h;

	memcpy(cost_, cost, m_ * sizeof *cost);
	while (1) {
		dijkstra(s);
		if (pi[t] == INF)
			break;
		push(s, t);
		for (h = 0; h < m_; h++) {
			int u = uu[h], v = vv[h];

			if (pi[u] != INF && pi[v] != INF)
				cost_[h] += pi[u] - pi[v];
		}
	}
	c = 0;
	for (h = 0; h < m_; h++)
		c += cost[h] * cc[h << 1 ^ 1];
	return c;
}

int main() {
	static int ii[K];
	int n, m, k, t, c, d, h, i, j, s, u, v, x;

	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
	for (h = 0; h < k; h++)
		scanf("%d", &ii[h]), ii[h]--;
	while (m--) {
		scanf("%d%d", &i, &j), i--, j--;
		add(i, j), add(j, i);
	}
	t = n + k + 1;
	n_ = n * t + 1;
	m_ = 0;
	for (i = 0; i < n; i++)
		for (s = 0; s < t - 1; s++) {
			struct L *l;

			u = i * t + s;
			for (l = aa[i].next; l; l = l->next) {
				j = l->j;
				v = j * t + s + 1;
				for (x = 1; x <= k; x++)
					link(u, v, 1, c + (x * 2 - 1) * d);
			}
		}
	for (i = 0; i < n; i++)
		for (s = 0; s < t - 1; s++) {
			u = i * t + s, v = u + 1;
			link(u, v, k, i == 0 ? 0 : c);
		}
	for (h = 0; h < k; h++)
		link(n_ - 1, ii[h] * t + 0, 1, 0);
	printf("%d\n", edmonds_karp(n_ - 1, 0 * t + t - 1));
	return 0;
}

