import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    // Constants: maximum values from original code (not used as array sizes, but for INF)
    static final int INF = 0x3f3f3f3f;

    // Graph structures
    static List<Integer>[] aa; // original adjacency list
    static List<Integer>[] aa_; // flow network adjacency list (stores edge indices h_)

    // Flow network edge data
    static int[] uu, vv, uv, cost, cost_;
    static int[] cc; // capacity array: for edge h, forward is cc[2*h], reverse is cc[2*h+1]
    static int m_; // number of links (each link creates two directed edges)

    // Dijkstra's algorithm data (heap)
    static int[] pi, kk, bb; // potentials, distance rank, best edge
    static int[] pq, iq; // priority queue (1-indexed) and inverse mapping
    static int cnt; // number of elements in heap

    // Helper: child index for heap (1-indexed)
    static int i2(int i) {
        int child = i * 2;
        if (child > cnt) return 0;
        if (child < cnt && lt(pq[child + 1], pq[child])) return child + 1;
        return child;
    }

    // Comparison: lexicographic on (pi, kk)
    static boolean lt(int u, int v) {
        return pi[u] < pi[v] || (pi[u] == pi[v] && kk[u] < kk[v]);
    }

    // Move element up the heap
    static void pq_up(int u) {
        int i = iq[u];
        int j;
        while ((j = i / 2) > 0 && lt(u, pq[j])) {
            pq[i] = pq[j];
            iq[pq[j]] = i;
            i = j;
        }
        pq[i] = u;
        iq[u] = i;
    }

    // Move element down the heap
    static void pq_dn(int u) {
        int i = iq[u];
        int j;
        while ((j = i2(i)) > 0 && lt(pq[j], u)) {
            pq[i] = pq[j];
            iq[pq[j]] = i;
            i = j;
        }
        pq[i] = u;
        iq[u] = i;
    }

    // Add element to heap (assume not present)
    static void pq_add(int u) {
        iq[u] = ++cnt;
        pq_up(u);
    }

    // Remove the top element (minimum)
    static int pq_remove_first() {
        int u = pq[1];
        int v = pq[cnt--];
        iq[v] = 1;
        pq_dn(v);
        return u;
    }

    // Add an edge to the flow network
    static void link(int u, int v, int cap, int cos) {
        int h = m_++;
        uu[h] = u;
        vv[h] = v;
        uv[h] = u ^ v;
        cost[h] = cos;
        cc[2 * h] = cap;       // forward capacity
        cc[2 * h + 1] = 0;      // reverse capacity initially zero
        // Add directed edges to adjacency lists
        aa_[u].add(2 * h);      // forward edge from u
        aa_[v].add(2 * h + 1);  // reverse edge from v
    }

    // Dijkstra with potentials (Johnson's algorithm)
    static void dijkstra(int s) {
        // Initialize distances to INF
        for (int i = 0; i < pi.length; i++) pi[i] = INF;
        pi[s] = 0;
        kk[s] = 0; // not strictly necessary but initialized
        cnt = 0;
        pq_add(s);
        while (cnt > 0) {
            int u = pq_remove_first();
            int k = kk[u] + 1; // for tie-breaking when updating
            for (int h_ : aa_[u]) {
                if (cc[h_] == 0) continue; // edge not usable
                int h = h_ / 2;
                boolean forward = (h_ % 2 == 0);
                int p = pi[u] + (forward ? cost_[h] : -cost_[h]);
                int v = u ^ uv[h];
                if (pi[v] == INF) {
                    pi[v] = p;
                    kk[v] = k;
                    bb[v] = h_;
                    pq_add(v);
                } else if (p < pi[v] || (p == pi[v] && kk[v] > k)) {
                    pi[v] = p;
                    kk[v] = k;
                    bb[v] = h_;
                    pq_up(v);
                }
            }
        }
    }

    // Push one unit of flow along the found shortest path
    static void push(int s, int t) {
        int u = t;
        while (u != s) {
            int h_ = bb[u];
            int h = h_ / 2;
            cc[h_]--;       // forward edge: decrease capacity
            cc[h_ ^ 1]++;    // reverse edge: increase capacity
            u = u ^ uv[h];
        }
    }

    // Min-cost max-flow (successive shortest augmenting path)
    static int edmonds_karp(int s, int t) {
        // Copy costs to work array (potentials will be added)
        System.arraycopy(cost, 0, cost_, 0, m_);
        while (true) {
            dijkstra(s);
            if (pi[t] == INF) break;
            push(s, t);
            // Update costs with potentials
            for (int h = 0; h < m_; h++) {
                int u = uu[h];
                int v = vv[h];
                if (pi[u] != INF && pi[v] != INF) {
                    cost_[h] += pi[u] - pi[v];
                }
            }
        }
        // Sum the cost of flow on reverse edges (flow amount * cost)
        int totalCost = 0;
        for (int h = 0; h < m_; h++) {
            totalCost += cost[h] * cc[2 * h + 1]; // flow on reverse edge = amount sent
        }
        return totalCost;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        // Read initial positions (0-indexed)
        int[] ii = new int[k];
        for (int i = 0; i < k; i++) {
            ii[i] = sc.nextInt() - 1;
        }

        // Build original graph adjacency list
        aa = new ArrayList[n];
        for (int i = 0; i < n; i++) aa[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            aa[a].add(b);
            aa[b].add(a);
        }

        // Time steps
        int t = n + k + 1;
        int n_ = n * t + 1; // number of vertices in flow network

        // First pass: count number of links (m_)
        int linkCount = 0;
        // Edges for movement between cities
        for (int i = 0; i < n; i++) {
            int deg = aa[i].size();
            for (int s = 0; s < t - 1; s++) {
                linkCount += deg * k; // for each neighbour and each x
            }
        }
        // Edges for staying (self-loop through time)
        for (int i = 0; i < n; i++) {
            linkCount += (t - 1); // one per time step
        }
        // Edges from super source to initial positions
        linkCount += k;

        // Allocate arrays for flow network
        uu = new int[linkCount];
        vv = new int[linkCount];
        uv = new int[linkCount];
        cost = new int[linkCount];
        cost_ = new int[linkCount];
        cc = new int[2 * linkCount]; // two capacities per link

        // Build adjacency for flow network
        aa_ = new ArrayList[n_];
        for (int i = 0; i < n_; i++) aa_[i] = new ArrayList<>();

        m_ = 0; // reset counter

        // Add movement edges: from i at time s to neighbor j at time s+1, for x=1..k
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                for (int j : aa[i]) {
                    int v = j * t + (s + 1);
                    for (int x = 1; x <= k; x++) {
                        link(u, v, 1, c + (2 * x - 1) * d);
                    }
                }
            }
        }

        // Add staying edges: from i at time s to i at time s+1, capacity k
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                int v = u + 1;
                link(u, v, k, (i == 0 ? 0 : c));
            }
        }

        // Add source edges: from super source (index n_-1) to initial positions at time 0
        int source = n_ - 1;
        for (int h = 0; h < k; h++) {
            int pos = ii[h];
            link(source, pos * t, 1, 0);
        }

        // Sink is city 0 at time t-1
        int sink = 0 * t + (t - 1); // = t-1

        // Allocate arrays for Dijkstra
        pi = new int[n_];
        kk = new int[n_];
        bb = new int[n_];
        pq = new int[n_ + 1]; // 1-indexed, size n_+1
        iq = new int[n_];

        int result = edmonds_karp(source, sink);
        System.out.println(result);
    }
}
